/* @lc app=leetcode id=3240 lang=kotlin */ class Solution { fun minFlips(grid: Array<IntArray>): Int = grid.size.let { m -> grid[0].size.let { n -> (0 until m / 2).sumOf { i -> (0 until n / 2).sumOf { j -> (grid[i][j] + grid[i][n - 1 - j] + grid[m - 1 - i][j] + grid[m - 1 - i][n - 1 - j]).let { c -> minOf(c, 4 - c) } } }.let { quads -> (listOf<Pair<Int, Int>>() + (if (m % 2 == 1) (0 until n / 2).map { grid[m / 2][it] to grid[m / 2][n - 1 - it] } else listOf()) + (if (n % 2 == 1) (0 until m / 2).map { grid[it][n / 2] to grid[m - 1 - it][n / 2] } else listOf())).let { pr -> pr.count { it.first != it.second }.let { diff -> quads + diff + (if (diff == 0 && pr.count { it.first == 1 } % 2 == 1) 2 else 0) + (if (m % 2 == 1 && n % 2 == 1) grid[m / 2][n / 2] else 0) } } } } } }